import { INVENTORIES } from "../constants";
import Chat from "./Chat";
import InventorySlots from "./InventorySlots";
import { InventoryProvider } from "./InventorySlots/provider";
import { useApp } from "../provider";

export default function InventoryGroup({
  type,
  chatTarget,
  pickUpCallback = () => {},
  allowRightClickPickup = true,
  canPutDown = () => true,
  ...props
}) {

  const { inventories } = useApp();

  const exportInventoryToCSV = async () => {
  const inventory = inventories[type] || [];

  const headers = ["slot", "id", "count"];
  const rows = inventory
  .map((item, index) => ({ item, index }))
  .filter(({ item }) => item.id !== null)
  .map(({ item, index }) => [index, item.id, item.count]);

  const csvContent =
    [headers, ...rows]
      .map((row) => row.join(","))
      .join("\n");

  try {
    await navigator.clipboard.writeText(csvContent);
    alert("Inventory copied to clipboard as CSV!");
  } catch (err) {
    console.error("Failed to copy:", err);
  }
};

  return (
    <div className="w-min">

      <button onClick={exportInventoryToCSV} className="fixed bottom-4 right-4 z-50 px-3 py-1 bg-gray-700 text-white text-sm rounded shadow-lg">
        Export CSV
      </button>

      <InventoryProvider
        type={type}
        pickUpCallback={pickUpCallback}
        allowRightClickPickup={allowRightClickPickup}
        canPutDown={canPutDown}
      >
        <InventorySlots
          {...props}
          rows={INVENTORIES?.[type]?.rows}
          cols={INVENTORIES?.[type]?.cols}
        />
        {chatTarget && <Chat />}
      </InventoryProvider>
    </div>
  );
}
